const request = $('Webhook').item.json;
const expectedKey = $env.NINF_N8N_WEBHOOK_API_KEY;
const receivedKey = request.headers?.['x-ness-webhook-key'];
if (typeof expectedKey !== 'string' || expectedKey.length < 32 || receivedKey !== expectedKey) {
  throw new Error('Unauthorized webhook request');
}
const body = request.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  throw new Error('Invalid incident payload');
}
const field = (value, fallback, maxLength = 2000) => {
  if (typeof value !== 'string' && typeof value !== 'number') return fallback;
  return String(value).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, maxLength) || fallback;
};
const escapeHtml = (value) => String(value).replace(/[&<>\"']/g, (char) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;'
}[char]));
const eventName = field(body.event_name, 'Incidente sem título', 160);
const customerName = field(body.customer_name, 'Ness', 160);
const hostName = field(body.host_name, 'unknown', 160);
const severity = field(body.severity_label ?? body.severity, 'average', 80);
const desc = field(body.clean_payload?.description ?? body.clean_payload?.trigger?.description, 'Sem detalhes adicionais.');
const fingerprint = field(body.fingerprint, 'N/A', 160);
const emailSubject = '[NOC-ALERT] ' + customerName + ' | Host: ' + hostName + ' | Event: ' + eventName + ' | Fingerprint: ' + fingerprint;
const emailHtml = '<p><strong>Alerta NOC: Incidente Detectado</strong></p>\n' +
  '<p><strong>Cliente:</strong> ' + escapeHtml(customerName) + '</p>\n' +
  '<p><strong>Equipamento:</strong> ' + escapeHtml(hostName) + '</p>\n' +
  '<p><strong>Evento:</strong> ' + escapeHtml(eventName) + '</p>\n' +
  '<p><strong>Severidade:</strong> ' + escapeHtml(severity) + '</p><hr/>\n' +
  '<p><strong>Descrição do Ocorrido:</strong><br/>' + escapeHtml(desc) + '</p><hr/>\n' +
  '<p><small>Fingerprint: ' + escapeHtml(fingerprint) + '</small></p>';
const whatsappText = '*Alerta NOC: Incidente Detectado*\n\n' +
  '*Cliente:* ' + customerName + '\n*Equipamento:* ' + hostName + '\n' +
  '*Evento:* ' + eventName + '\n*Severidade:* ' + severity + '\n\n' +
  '*Descrição do Ocorrido*:\n' + desc;
return {
  "options": { "delay": 1200, "presence": "composing" },
  "text": whatsappText,
  "emailSubject": emailSubject,
  "emailHtml": emailHtml
};
